import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.CZqXuAiL.js";const h=JSON.parse('{"title":"Configuration Reference","description":"Every Blue Plugin Installer setting — the admin option, search parameters, and the conf.yml manifest.","frontmatter":{"title":"Configuration Reference","description":"Every Blue Plugin Installer setting — the admin option, search parameters, and the conf.yml manifest."},"headers":[],"relativePath":"blue-plugin-installer/configuration/reference.md","filePath":"blue-plugin-installer/configuration/reference.md","lastUpdated":null}'),n={name:"blue-plugin-installer/configuration/reference.md"};function a(i,e,c,s,l,p){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><h2 id="admin-settings" tabindex="-1">Admin settings <a class="header-anchor" href="#admin-settings" aria-label="Permalink to &quot;Admin settings&quot;">​</a></h2><p>Managed at <strong>Admin → Extensions → Blue Plugin Installer</strong> (<code>/admin/extensions/blueplugininstaller</code>). Values are stored by Blueprint&#39;s extension settings store.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>curseforge_api_key</code></td><td>string</td><td><em>(empty)</em></td><td>Your CurseForge API key, sent as <code>x-api-key</code> on every CurseForge request. <strong>Server-side only</strong> — users never see it. Leave empty to disable CurseForge (the other four providers still work). Get a key at <a href="https://console.curseforge.com/" target="_blank" rel="noreferrer">https://console.curseforge.com/</a>. The key is required by the settings form; paste any placeholder if you only use other providers.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Which providers need keys?</p><p>Only <strong>CurseForge</strong>. Modrinth, Hangar, SpigotMC (via the Spiget API), and Polymart are queried without credentials.</p></div><h2 id="search-parameters" tabindex="-1">Search parameters <a class="header-anchor" href="#search-parameters" aria-label="Permalink to &quot;Search parameters&quot;">​</a></h2><p>Query parameters accepted by the search endpoint (used by the UI; documented for custom API clients — see <a href="./../user-guide/api">API Reference</a>):</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>category</code></td><td>string</td><td><code>modrinth</code></td><td>Provider: <code>modrinth</code>, <code>curseforge</code>, <code>hangar</code>, <code>spigotmc</code>, <code>polymart</code>.</td></tr><tr><td><code>page</code></td><td>int ≥ 1</td><td><code>1</code></td><td>Page number.</td></tr><tr><td><code>page_size</code></td><td>int</td><td><code>6</code></td><td>Results per page.</td></tr><tr><td><code>search_query</code></td><td>string</td><td><em>(empty)</em></td><td>Free-text search.</td></tr><tr><td><code>type</code></td><td>string</td><td><em>(empty)</em></td><td>Loader/type filter (e.g. <code>bukkit</code>, <code>paper</code>, <code>spigot</code>). Empty = all types.</td></tr><tr><td><code>sort_by</code></td><td>string</td><td>provider default</td><td>Modrinth: <code>relevance</code>, <code>downloads</code>, <code>follows</code>, <code>newest</code>, <code>updated</code> (fallback <code>downloads</code>). CurseForge: numeric sort field (fallback <code>6</code> = total downloads).</td></tr><tr><td><code>minecraft_version</code></td><td>string</td><td><em>(empty)</em></td><td>MC version filter, e.g. <code>1.20.1</code>. Empty = all versions.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Behavior since 1.0.3</p><p>Omitting <code>sort_by</code> or <code>type</code> previously produced a <code>500</code> (the empty values were forwarded to the provider verbatim). Since 1.0.3 the backend applies the defaults above and skips empty facets.</p></div><h2 id="extension-manifest-conf-yml" tabindex="-1">Extension manifest (<code>conf.yml</code>) <a class="header-anchor" href="#extension-manifest-conf-yml" aria-label="Permalink to &quot;Extension manifest (`conf.yml`)&quot;">​</a></h2><p>Located at <code>blueprint/blueplugininstaller/conf.yml</code> in the repo. You normally never edit these — Blueprint reads them at install time.</p><table tabindex="0"><thead><tr><th>Key</th><th>Value</th><th>Purpose</th></tr></thead><tbody><tr><td><code>info.identifier</code></td><td><code>blueplugininstaller</code></td><td>Extension identifier — used in all paths and URLs.</td></tr><tr><td><code>info.version</code></td><td><code>1.0.3</code></td><td>Extension version (shown on the admin page).</td></tr><tr><td><code>info.target</code></td><td><code>beta-2026-06</code></td><td>Blueprint version the extension targets.</td></tr><tr><td><code>info.compatibility</code></td><td><code>beta-2026-01/02/05/06</code></td><td>Blueprint versions accepted at install time.</td></tr><tr><td><code>admin.view</code> / <code>admin.controller</code></td><td><code>view.blade.php</code> / <code>controller.php</code></td><td>The admin settings page.</td></tr><tr><td><code>dashboard.components</code></td><td><code>components</code></td><td>React components mounted by Blueprint&#39;s build.</td></tr><tr><td><code>requests.app</code></td><td><code>controllers</code></td><td>Client API controllers.</td></tr><tr><td><code>requests.routers.client</code></td><td><code>routes.php</code></td><td>Client API router, mounted at <code>/api/client/extensions/blueplugininstaller</code>.</td></tr></tbody></table>',12)])])}const m=t(n,[["render",a]]);export{h as __pageData,m as default};
